<template>
  <el-dialog title="店铺分仓规则" :visible.sync="visible" width="min(1040px, 96vw)" top="5vh" append-to-body :close-on-click-modal="false">
    <div v-loading="loading" class="allocation-layout">
      <div class="shop-summary"><div><strong>{{ shop.channel_name }}</strong><span class="muted">渠道 ID：{{ shop.channel_id }}</span></div><el-tag size="small" type="info">{{ revision ? '规则 v' + revision : '尚未配置' }}</el-tag></div>
      <template v-if="policy">
        <nav class="section-nav" aria-label="分仓规则分组"><el-button type="text" @click="goSection('execution')">1 执行方式</el-button><el-button type="text" @click="goSection('warehouses')">2 允许仓与顺序</el-button><el-button type="text" @click="goSection('strategy')">3 选仓策略</el-button><el-button type="text" @click="goSection('splitting')">4 库存与拆分</el-button></nav>
        <section ref="execution" class="rule-section">
          <div class="section-title"><span class="step">1</span><h3>何时执行分仓</h3><div class="enable-control"><span>启用分仓</span><el-switch v-model="policy.enabled" :active-value="1" :inactive-value="0" aria-label="启用分仓" /></div></div>
          <div v-if="!policy.enabled" class="notice">分仓已关闭。可以继续编辑规则，启用并保存后才允许执行分仓。</div>
          <el-radio-group v-model="policy.execution_mode" class="option-grid" aria-label="分仓执行方式">
            <el-radio label="MANUAL" class="option"><span class="option-title">人工执行分仓</span><span class="option-description">审核通过后，由操作人员在订单中发起分仓，按本页规则选仓。</span><span class="option-outcome">人工发起 → 生成发货单</span></el-radio>
            <el-radio label="AUTO" class="option"><span class="option-title">满足条件自动分仓</span><span class="option-description">审核通过、逻辑预占更新或解除阻断后，自动检查并执行分仓。</span><span class="option-outcome">条件满足 → 自动生成发货单</span></el-radio>
          </el-radio-group>
          <div class="inline-setting"><div><strong>余量自动补充分仓</strong><p class="muted">部分分仓后，补货满足条件时继续处理余量；关闭则由人工发起。仅自动模式生效。</p></div><el-switch v-model="policy.auto_replenish" :active-value="1" :inactive-value="0" :disabled="policy.execution_mode !== 'AUTO'" aria-label="余量自动补充分仓" /></div>
          <p class="boundary">分仓只生成发货单，不代表已发货，也不会自动下发 WMS。</p>
        </section>
        <section ref="warehouses" class="rule-section warehouse-section">
          <div class="section-title"><span class="step">2</span><h3>允许哪些仓，按什么顺序</h3><el-tag size="mini" type="info">按虚拟仓配置</el-tag></div>
          <el-form label-position="top"><div class="scope-grid">
            <el-form-item label="货主"><el-select v-model="policy.owner_code" filterable placeholder="选择货主" aria-label="分仓货主" @change="ownerChanged"><el-option v-for="owner in owners" :key="owner.owner_code" :value="owner.owner_code" :label="owner.owner_name + '（' + owner.owner_code + '）'" /></el-select></el-form-item>
            <el-form-item label="允许的虚拟仓"><el-select v-model="policy.warehouse_order" multiple filterable :multiple-limit="100" :disabled="!policy.owner_code" placeholder="选择该店铺允许使用的虚拟仓" aria-label="允许的虚拟仓" @change="cleanPriorities"><el-option v-for="store in available" :key="store.wms_simulation_code" :value="store.wms_simulation_code" :label="storeLabel(store)" /></el-select></el-form-item>
          </div></el-form>
          <div class="subheading"><strong>默认尝试顺序</strong><span class="muted">无省份规则时使用；也用于省份优先仓不足后的补充。</span></div>
          <div v-if="!policy.warehouse_order.length" class="empty-state">先选择货主和允许的虚拟仓，再设置顺序。</div>
          <div v-for="(code, index) in policy.warehouse_order" :key="code" class="rank-row"><span class="rank">{{ index + 1 }}</span><div class="warehouse-name"><strong>{{ virtualLabel(code) }}</strong><div class="muted">{{ physicalLabel(code) }}</div></div><div class="rank-actions"><el-button type="text" :disabled="index === 0" :aria-label="'默认仓库上移 ' + code" @click="move(policy.warehouse_order, index, -1)">上移</el-button><el-button type="text" :disabled="index === policy.warehouse_order.length - 1" :aria-label="'默认仓库下移 ' + code" @click="move(policy.warehouse_order, index, 1)">下移</el-button></div></div>
          <p class="boundary">不同虚拟仓分别生成发货单，即使对应同一个实体仓也不合并；实际包裹以仓库回传为准。</p>
          <div class="subheading"><strong>省份优先仓</strong><el-tag size="mini" type="info">可选 · {{ priorities.length }} 个省份</el-tag></div>
          <p class="muted">只能选择上方允许的虚拟仓。选仓策略决定省份顺序是否优先于整单；未配置或收货省份缺失时使用默认顺序。</p>
          <div v-for="(row, index) in priorities" :key="index" class="province-rule">
            <div class="province-row"><el-select v-model="row.province" filterable placeholder="收货省份" aria-label="收货省份"><el-option v-for="province in provinces" :key="province" :label="province" :value="province" :disabled="priorities.some(other => other !== row && other.province === province)" /></el-select><el-select v-model="row.stores" multiple filterable placeholder="按优先顺序选择虚拟仓" aria-label="省份优先虚拟仓"><el-option v-for="code in policy.warehouse_order" :key="code" :value="code" :label="virtualLabel(code)" /></el-select><el-button type="text" :aria-label="'删除省份规则 ' + (index + 1)" @click="priorities.splice(index, 1)">删除</el-button></div>
            <div v-for="(code, rank) in row.stores" :key="code" class="province-rank"><span>{{ rank + 1 }}. {{ virtualLabel(code) }}</span><div><el-button type="text" :disabled="rank === 0" :aria-label="'省份仓库上移 ' + code" @click="move(row.stores, rank, -1)">上移</el-button><el-button type="text" :disabled="rank === row.stores.length - 1" :aria-label="'省份仓库下移 ' + code" @click="move(row.stores, rank, 1)">下移</el-button></div></div>
          </div>
          <el-button size="small" icon="el-icon-plus" :disabled="!policy.warehouse_order.length || priorities.length >= provinces.length" @click="priorities.push({ province: '', stores: [] })">添加省份优先规则</el-button>
        </section>
        <section ref="strategy" class="rule-section strategy-section">
          <div class="section-title"><span class="step">3</span><h3>优先整单，还是优先省份仓</h3></div>
          <el-radio-group v-model="policy.strategy" class="option-grid" aria-label="选仓策略">
            <el-radio label="FEWEST_SHIPMENTS" class="option"><span class="option-title">优先整单</span><span class="option-description">优先由一个虚拟仓满足整单；组合分仓时优先较少的新增发货单。省份与默认顺序用于同等方案择优。</span><span class="option-outcome">尽量减少新增发货单</span></el-radio>
            <el-radio label="REGION_FIRST" class="option"><span class="option-title">优先省份配置仓</span><span class="option-description">先按收货省份配置的顺序尝试，不足时再按默认顺序补充；未配置省份规则时直接使用默认顺序。</span><span class="option-outcome">优先遵循选仓顺序</span></el-radio>
          </el-radio-group>
          <div class="example"><strong>示例</strong><p>订单需要同一 SKU 10 件，省份首选 V1 有 6 件，V2 有 10 件；允许多仓和同 SKU 拆分，且上限足够时：</p><div>优先整单：V2 分 10 件，生成 1 张发货单。</div><div>优先省份配置仓：V1 分 6 件、V2 分 4 件，生成 2 张发货单。</div><span class="muted">仅用于解释策略，实际结果仍受库存、原有锁库及下方限制约束。</span></div>
        </section>
        <section ref="splitting" class="rule-section split-section">
          <div class="section-title"><span class="step">4</span><h3>库存不足与拆分限制</h3></div>
          <div class="condition-grid">
            <div class="condition"><div class="condition-title"><strong>允许多虚拟仓发货</strong><el-switch v-model="policy.allow_multi" :active-value="1" :inactive-value="0" aria-label="允许多虚拟仓发货" @change="multiChanged" /></div><p class="muted">{{ policy.allow_multi ? '可组合多个允许仓，仍受下方累计仓数与单数限制。' : '整个订单限一个虚拟仓，后续补充分仓也计入。' }}</p></div>
            <div class="condition"><div class="condition-title"><strong>同 SKU 跨虚拟仓拆分</strong><el-switch v-model="policy.allow_split_sku" :active-value="1" :inactive-value="0" :disabled="!policy.allow_multi" aria-label="同SKU跨虚拟仓拆分" /></div><p class="muted">{{ !policy.allow_multi ? '先开启多虚拟仓发货，才能启用此项。' : policy.allow_split_sku ? '同一 SKU 可由多个虚拟仓共同满足。' : '同一 SKU 固定一个虚拟仓，后续余量也沿用原仓。' }}</p></div>
            <div class="condition partial-condition"><div class="condition-title"><strong>允许部分分仓</strong><el-switch v-model="policy.allow_partial" :active-value="1" :inactive-value="0" aria-label="允许部分分仓" @change="value=>{if(!value)policy.allow_bundle_partial_components=0}" /></div><p class="muted">{{ policy.allow_partial ? '先分配已逻辑预占且可分仓的数量，余量后续处理；原单数量与金额保持完整。' : '本次剩余需求必须全部满足，才能新增分仓占用。' }}</p><div v-if="policy.allow_partial" class="threshold">首次至少满足 <el-input-number v-model="policy.min_first_allocation_percent" :min="0" :max="100" :precision="0" controls-position="right" aria-label="首次最低满足比例" /> %<p class="muted">首次可分仓件数 ÷ 原单总件数；0 表示不限制。低于比例不新增占用，后续补充不受此比例限制。</p></div></div>
            <div class="condition"><div class="condition-title"><strong>套内组件跨虚拟仓发货</strong><el-switch v-model="policy.allow_bundle_split" :active-value="1" :inactive-value="0" :disabled="!policy.allow_multi" aria-label="套内组件跨虚拟仓发货"/></div><p class="muted">默认每套组件在同一虚拟仓；不同整套可分仓。开启后，同一套的组件也可从不同虚拟仓发出。</p></div>
            <div class="condition"><div class="condition-title"><strong>套内组件部分发货</strong><el-switch v-model="policy.allow_bundle_partial_components" :active-value="1" :inactive-value="0" :disabled="!policy.allow_partial" aria-label="套内组件部分发货"/></div><p class="muted">默认只分配完整套数。开启后允许先发部分组件，未齐套部分持续显示待发，不视为整套完成。</p></div>
            <div class="condition limits-condition"><strong>订单累计上限</strong><div class="limit-row"><label>虚拟仓数</label><el-input-number v-model="policy.max_virtual_warehouses" :disabled="!policy.allow_multi" :min="0" :max="100" :precision="0" controls-position="right" aria-label="最多虚拟仓数" /><span class="muted">{{ policy.allow_multi ? '0 = 不额外限制' : '当前固定 1 个仓' }}</span></div><div class="limit-row"><label>发货单数</label><el-input-number v-model="policy.max_shipments" :min="0" :max="100" :precision="0" controls-position="right" aria-label="最多发货单数" /><span class="muted">0 = 不额外限制</span></div><p class="muted">包含已有分仓与后续补充产生的发货单；发货单数不是实际包裹数。</p></div>
          </div>
        </section>
        <div class="effective-summary"><strong>当前规则摘要</strong><template v-if="policy.enabled"><p>{{ policy.execution_mode === 'AUTO' ? '满足条件自动分仓' : '人工发起分仓' }} · {{ policy.strategy === 'REGION_FIRST' ? '优先省份配置仓' : '优先整单' }} · {{ policy.allow_partial ? '允许部分分仓' : '剩余需求全部满足后分仓' }}</p><p>已选 {{ policy.warehouse_order.length }} 个允许仓、{{ priorities.length }} 个省份规则；订单累计{{ !policy.allow_multi ? '限 1 个虚拟仓' : policy.max_virtual_warehouses ? '最多 ' + policy.max_virtual_warehouses + ' 个虚拟仓' : '不额外限制虚拟仓数' }}，{{ policy.max_shipments ? '最多 ' + policy.max_shipments + ' 张发货单' : '不额外限制发货单数' }}。</p><p v-if="policy.execution_mode === 'AUTO'">部分分仓后的余量：{{ policy.auto_replenish ? '满足条件后自动补充' : '需人工发起补充' }}。</p></template><p v-else>分仓关闭，保存后不执行分仓；以上配置保留。</p></div>
        <p class="boundary"><i class="el-icon-lock" /> 原渠道锁库沿用原仓、原批次，原仓不在允许范围时会阻止分仓。订单首次分仓成功后固定当时的规则，后续仅处理余量；本次修改不改写已有分仓或发货单。</p>
      </template>
    </div>
    <span slot="footer"><el-button :disabled="saving" @click="visible=false">取消</el-button><el-button type="primary" :disabled="loading || !policy" :loading="saving" @click="save">保存分仓规则</el-button></span>
  </el-dialog>
</template>
<script>
import { allocationConfig, saveAllocationConfig } from '@/api/order'
export default {
  data() { return { visible: false, loading: false, saving: false, shop: {}, policy: null, revision: 0, stores: [], priorities: [], provinces: ['北京', '天津', '河北', '山西', '内蒙古', '辽宁', '吉林', '黑龙江', '上海', '江苏', '浙江', '安徽', '福建', '江西', '山东', '河南', '湖北', '湖南', '广东', '广西', '海南', '重庆', '四川', '贵州', '云南', '西藏', '陕西', '甘肃', '青海', '宁夏', '新疆', '香港', '澳门', '台湾'] } },
  computed: { owners() { return [...new Map(this.stores.map(s => [s.owner_code, s])).values()] }, available() { return this.stores.filter(s => s.owner_code === this.policy.owner_code) }, storesByCode() { return new Map(this.stores.map(store => [store.wms_simulation_code, store])) } },
  methods: {
    async open(shop) { this.shop = shop; this.visible = true; this.loading = true; this.policy = null; try { const r = (await allocationConfig(shop.channel_id)).data; this.policy = { execution_mode: 'MANUAL', auto_replenish: 0, allow_bundle_split: 0, allow_bundle_partial_components: 0, strategy: 'FEWEST_SHIPMENTS', max_virtual_warehouses: 0, max_shipments: 0, min_first_allocation_percent: 0, ...r.policy, warehouse_order: [...r.policy.warehouse_order] }; this.stores = r.warehouses; this.revision = r.revision; this.priorities = Object.entries(r.policy.province_priorities).map(([province, stores]) => ({ province, stores: [...stores] })) } finally { this.loading = false } },
    storeLabel(store) { return `${store.wms_simulation_name}（${store.wms_simulation_code}） / ${store.real_store_name}（${store.real_store_code}）` },
    virtualLabel(code) { const s = this.storesByCode.get(code); return s ? `${s.wms_simulation_name}（${code}）` : `${code}（已停用或映射异常，请移除）` },
    physicalLabel(code) { const s = this.storesByCode.get(code); return s ? `实体仓：${s.real_store_name}（${s.real_store_code}）` : '无法获取实体仓映射' },
    goSection(name) { this.$refs[name].scrollIntoView({ block: 'start' }) },
    multiChanged(value) { if (!value) { this.policy.allow_split_sku = 0; this.policy.allow_bundle_split = 0 } },
    ownerChanged() { this.policy.warehouse_order = []; this.priorities = [] },
    cleanPriorities() { this.priorities.forEach(row => { row.stores = row.stores.filter(code => this.policy.warehouse_order.includes(code)) }) },
    move(rows, index, step) { const target = index + step; if (target < 0 || target >= rows.length) return; const item = rows.splice(index, 1)[0]; rows.splice(target, 0, item) },
    async save() { if (this.saving || !this.policy) return; if (this.policy.enabled && (!this.policy.owner_code || !this.policy.warehouse_order.length)) return this.$message.warning('启用分仓前，请选择货主和至少一个允许的虚拟仓'); for (const key of ['max_virtual_warehouses', 'max_shipments', 'min_first_allocation_percent']) { if (!Number.isInteger(this.policy[key]) || this.policy[key] < 0 || this.policy[key] > 100) return this.$message.warning('请填写 0 到 100 的整数上限与首次满足比例，0 表示不额外限制') } const priorities = {}; for (const row of this.priorities) { if (!row.province || !row.stores.length) return this.$message.warning('请完整填写省份优先仓，或删除空白规则'); if (priorities[row.province]) return this.$message.warning('省份不能重复'); priorities[row.province] = row.stores } this.saving = true; try { await saveAllocationConfig({ channel_id: this.shop.channel_id, revision: this.revision, policy: { ...this.policy, province_priorities: priorities } }); this.visible = false; this.$message.success('分仓规则已保存'); this.$emit('changed') } finally { this.saving = false } }
  }
}
</script>
<style scoped>
